#include <iostream>

struct CantidadInvalida {};
struct SumaExcesiva {};

class Cantidad {
public:
    Cantidad() = default;
    explicit Cantidad(int valor) : unidades_{valor} {
        if (valor < 0 || valor > 1000) { throw CantidadInvalida{}; }
    }

    int valor() const noexcept { return unidades_; }
    Cantidad operator+(const Cantidad& otra) const;
private:
    int unidades_ = 0;
};

Cantidad Cantidad::operator+(const Cantidad& otra) const {
    // Calcula el resultado sin cambiar los operandos y comprueba su límite.
    (void)otra;
    return Cantidad{};
}

int main() {
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) { return 1; }
    Cantidad a{200}, b{350}, total;
    for (int i = 0; i < ordenes; ++i) {
        int op = 0, x = 0, y = 0;
        if (!(std::cin >> op >> x >> y)) { return 1; }
        std::cout << "Antes:A=" << a.valor() << ";B=" << b.valor() << ";Total=" << total.valor();
        const char* estado = "Operacion";
        try {
            if (op == 1) {
                Cantidad nueva_a{x}, nueva_b{y};
                a = nueva_a;
                b = nueva_b;
                estado = "Aceptada";
            } else if (op == 2) {
                total = a + b;
                estado = "Aceptada";
            } else if (op == 3) {
                total = total + a;
                estado = "Aceptada";
            } else if (op == 4) {
                total = b + a;
                estado = "Aceptada";
            } else if (op == 5) {
                total = a + a;
                estado = "Aceptada";
            }
        } catch (const CantidadInvalida&) {
            estado = "Rango";
        } catch (const SumaExcesiva&) {
            estado = "Suma";
        }
        std::cout << ";Estado:" << estado << ";Ahora:A=" << a.valor()
                  << ";B=" << b.valor() << ";Total=" << total.valor() << '\n';
    }
    std::cout << "Final:" << a.valor() << ':' << b.valor() << ':' << total.valor();

    return 0;
}

